      "key": "zotero",
      "name": "Zotero",
      "category": "Documents",
      "type": "winget",
      "id": "DigitalScholar.Zotero",
      "info": "Zotero is a free, easy-to-use tool to help you collect, organize, cite, and share your research materials.",
      "foss": true,
      "link": "https://www.zotero.org/"
    }
  ]
}
'@

# ---------------------------------------------------------------------------
# common.ps1 - shared helpers for every win-toolbox script.
# Must stay Windows PowerShell 5.1 compatible (no ternary, no ??, no classes).
# ---------------------------------------------------------------------------

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'   # Invoke-WebRequest is much faster without the progress bar
[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

# Upstream URLs of third-party scripts/binaries - the single place to change them.
$Urls = @{
    AdwCleaner     = 'https://adwcleaner.malwarebytes.com/adwcleaner?channel=release'
    WinGetInstall  = 'https://asheroto.com/winget'          # asheroto/winget-install
    MAS            = 'https://get.activated.win'            # Microsoft Activation Scripts (massgrave)
    OfficeToolPlus = 'https://officetool.plus'              # serves a .ps1 to PowerShell user agents
    WinUtil        = 'https://christitus.com/win'           # Chris Titus Tech WinUtil
    WinScript      = 'https://winscript.cc/irm'             # flick9000/winscript
}

# ---- output ---------------------------------------------------------------

function Write-Title {
    param([string]$Text)
    Write-Host ''
    Write-Host "== $Text ==" -ForegroundColor Cyan
}
function Write-Step { param([string]$Text) Write-Host "-> $Text" -ForegroundColor White;  Write-LogLine "STEP $Text" }
function Write-Ok   { param([string]$Text) Write-Host "   $Text" -ForegroundColor Green;  Write-LogLine "OK   $Text" }
function Write-Warn { param([string]$Text) Write-Host "   $Text" -ForegroundColor Yellow; Write-LogLine "WARN $Text" }
function Write-Fail { param([string]$Text) Write-Host "   $Text" -ForegroundColor Red;    Write-LogLine "FAIL $Text" }

function Read-MenuLine {
    # Line input seam - tests/smoke.ps1 replaces this to feed scripted input.
    param([string]$Prompt = '  Input')
    return (Read-Host $Prompt).Trim()
}

function Wait-AnyKey {
    param([string]$Prompt = 'Press any key to continue...')
    Write-Host ''
    Write-Host $Prompt -ForegroundColor DarkGray
    try { $null = [Console]::ReadKey($true) } catch { $null = Read-Host }
}

function Confirm-Action {
    param([Parameter(Mandatory)][string]$Question)
    $answer = Read-Host "$Question [y/N]"
    return ($answer -match '^(y|yes)$')
}

# ---- environment ----------------------------------------------------------

function Test-Command {
    param([Parameter(Mandatory)][string]$Name)
    return [bool](Get-Command $Name -ErrorAction SilentlyContinue)
}

function Test-IsAdmin {
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    return ([Security.Principal.WindowsPrincipal]$identity).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

function Invoke-Elevated {
    <#
    .SYNOPSIS
        Re-launches the current entry point with administrator rights.
    .DESCRIPTION
        Works for both execution styles: from a file (re-runs the file) and from
        `irm <url> | iex` (re-runs the irm|iex one-liner using $SelfUrl).
        Returns $true when a new elevated process was started - the caller should
        `return` in that case. Returns $false when already elevated.
    #>
    param(
        [Parameter(Mandatory)][string]$SelfUrl,
        [string]$Arguments = ''
    )
    if (Test-IsAdmin) { return $false }

    Write-Warn 'Administrator rights are required - requesting elevation (UAC prompt)...'
    $hostExe = (Get-Process -Id $PID).Path
    if (-not $hostExe) { $hostExe = 'powershell.exe' }

    if ($PSCommandPath) {
        $command = "& '$PSCommandPath' $Arguments"
    } else {
        $command = "irm '$SelfUrl' | iex"
    }
    Start-Process -FilePath $hostExe -Verb RunAs -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-Command', $command)
    return $true
}

function Update-SessionPath {
    # Pick up PATH changes made by installers (e.g. winget) without opening a new shell.
    $machine = [Environment]::GetEnvironmentVariable('Path', 'Machine')
    $user = [Environment]::GetEnvironmentVariable('Path', 'User')
    $env:Path = "$machine;$user"
}

# ---- network --------------------------------------------------------------

function Get-RemoteFile {
    param(
        [Parameter(Mandatory)][string]$Uri,
        [Parameter(Mandatory)][string]$OutFile,
        [int]$Retries = 3
    )
    for ($attempt = 1; $attempt -le $Retries; $attempt++) {
        try {
            Invoke-WebRequest -Uri $Uri -OutFile $OutFile -UseBasicParsing
            if ((Get-Item $OutFile).Length -gt 0) { return }
            throw 'downloaded file is empty'
        } catch {
            if ($attempt -ge $Retries) { throw "Download failed after $Retries attempts: $Uri ($_)" }
            Write-Warn "Download attempt $attempt failed ($_), retrying..."
            Start-Sleep -Seconds (2 * $attempt)
        }
    }
}

function Invoke-RemoteScript {
    <# Fetches a remote PowerShell script and runs it in the current session (irm | iex). #>
    param(
        [Parameter(Mandatory)][string]$Url,
        [string]$Name = $Url
    )
    Write-Step "Fetching $Name from $Url ..."
    $code = Invoke-RestMethod -Uri $Url -UseBasicParsing
    Invoke-Expression $code
}

# ---- logging ----------------------------------------------------------------

$LogState = @{ Path = $null }

function Start-Log {
    <# Starts a per-run log file under %TEMP%\win-toolbox\<name>_<host>_<stamp>.log. Write-Step/Ok/Warn/Fail append to it. #>
    param([Parameter(Mandatory)][string]$Name)
    $dir = Join-Path ([IO.Path]::GetTempPath()) 'win-toolbox'
    try {
        if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
        $stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
        $LogState.Path = Join-Path $dir ("{0}_{1}_{2}.log" -f $Name, $env:COMPUTERNAME, $stamp)
        Set-Content -LiteralPath $LogState.Path -Value ("win-toolbox {0} - {1} - {2}" -f $Name, (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $env:COMPUTERNAME) -Encoding UTF8
    } catch {
        $LogState.Path = $null
        Write-Warn "No writable log location - logging to screen only ($_)."
    }
    return $LogState.Path
}

function Write-LogLine {
    <# Appends a line to the current log file (no console output). #>
    param([string]$Text)
    if (-not $LogState.Path) { return }
    try { Add-Content -LiteralPath $LogState.Path -Value ("{0}  {1}" -f (Get-Date -Format 'HH:mm:ss'), $Text) -Encoding UTF8 } catch { $null = $_ }
}

# ---------------------------------------------------------------------------
# winget.ps1 - robust winget engine (needs common.ps1).
# ---------------------------------------------------------------------------

# ---- winget ---------------------------------------------------------------
# Robust winget handling, ported from Install-Software.ps1 (the PC-Gaming-Redists successor):
# find winget.exe even when PATH lacks it, run it with a timeout, verify success by the
# real installation state instead of trusting exit codes.

$WinGetState = @{ Path = $null; Version = ''; Flags = @('--accept-source-agreements', '--disable-interactivity'); Ready = $false }

function Invoke-Process {
    <#
    .SYNOPSIS
        Runs an executable with a timeout and captures stdout + stderr.
        Returns @{ Code; Output; TimedOut }. On timeout the whole process tree is killed
        (winget spawns the real installer as a child - .Kill() alone would leave it running).
    #>
    param(
        [Parameter(Mandatory)][string]$FilePath,
        [string[]]$ArgumentList = @(),
        [int]$TimeoutSeconds = 1200
    )
    $tmp = [IO.Path]::GetTempPath()
    $out = Join-Path $tmp ('win-toolbox-out-{0}.txt' -f [guid]::NewGuid().ToString('N'))
    $err = Join-Path $tmp ('win-toolbox-err-{0}.txt' -f [guid]::NewGuid().ToString('N'))
    try {
        $startArgs = @{ FilePath = $FilePath; PassThru = $true; NoNewWindow = $true; RedirectStandardOutput = $out; RedirectStandardError = $err }
        if ($ArgumentList.Count -gt 0) { $startArgs.ArgumentList = $ArgumentList }
        $p = Start-Process @startArgs
        if (-not $p.WaitForExit($TimeoutSeconds * 1000)) {
            try { & taskkill.exe /T /F /PID $p.Id 2>&1 | Out-Null } catch { $null = $_ }
            try { if (-not $p.HasExited) { $p.Kill() } } catch { $null = $_ }
            return [pscustomobject]@{ Code = -999; Output = 'timeout - process tree terminated'; TimedOut = $true }
        }
        $p.WaitForExit()
        $text = @()
        foreach ($f in @($out, $err)) {
            if (Test-Path -LiteralPath $f) {
                $content = Get-Content -LiteralPath $f -Raw -ErrorAction SilentlyContinue
                if ($content) { $text += $content.Trim() }
            }
        }
        return [pscustomobject]@{ Code = $p.ExitCode; Output = ($text -join "`n").Trim(); TimedOut = $false }
    } catch {
        return [pscustomobject]@{ Code = -998; Output = $_.Exception.Message; TimedOut = $false }
    } finally {
        Remove-Item -LiteralPath $out, $err -ErrorAction SilentlyContinue
    }
}

function Get-WinGetPath {
    <# Finds winget.exe - in elevated shells the PATH alias is often missing. Cached in $WinGetState.Path. #>
    if ($WinGetState.Path -and (Test-Path -LiteralPath $WinGetState.Path)) { return $WinGetState.Path }

    # 1. real package folder under Program Files\WindowsApps (works across accounts)
    $windowsApps = Join-Path $env:ProgramFiles 'WindowsApps'
    if ($windowsApps -and (Test-Path -LiteralPath $windowsApps)) {
        $dirs = Get-ChildItem -LiteralPath $windowsApps -Directory -ErrorAction SilentlyContinue |
                Where-Object { $_.Name -like 'Microsoft.DesktopAppInstaller_*_x64__*' -or $_.Name -like 'Microsoft.DesktopAppInstaller_*_arm64__*' } |
                Sort-Object Name -Descending
        foreach ($d in $dirs) {
            $p = Join-Path $d.FullName 'winget.exe'
            if (Test-Path -LiteralPath $p) { $WinGetState.Path = $p; return $p }
        }
    }
    # 2. registered Appx package of the current user
    try {
        $pkg = Get-AppxPackage -Name 'Microsoft.DesktopAppInstaller' -ErrorAction SilentlyContinue | Sort-Object Version -Descending | Select-Object -First 1
        if ($pkg -and $pkg.InstallLocation) {
            $p = Join-Path $pkg.InstallLocation 'winget.exe'
            if (Test-Path -LiteralPath $p) { $WinGetState.Path = $p; return $p }
        }
    } catch { $null = $_ }
    # 3. PATH / execution alias
    $cmd = Get-Command winget.exe -ErrorAction SilentlyContinue
    if ($cmd) { $WinGetState.Path = $cmd.Source; return $cmd.Source }
    if ($env:LOCALAPPDATA) {
        $alias = Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps\winget.exe'
        if (Test-Path -LiteralPath $alias) { $WinGetState.Path = $alias; return $alias }
    }
    return $null
}

function Initialize-WinGet {
    <#
    .SYNOPSIS
        Makes sure winget is usable and returns its path: locates winget.exe, installs it via
        winget-install (asheroto) when missing, detects the version (--disable-interactivity needs 1.4+).
    #>
    if ($WinGetState.Ready) { return $WinGetState.Path }
    $path = Get-WinGetPath
    if (-not $path) {
        Write-Step 'WinGet not found - installing via winget-install (asheroto)...'
        Invoke-RemoteScript -Url $Urls.WinGetInstall -Name 'winget-install'
        Update-SessionPath
        $WinGetState.Path = $null
        $path = Get-WinGetPath
    }
    if (-not $path) { throw 'WinGet is not available. Install "App Installer" from the Microsoft Store, open a new terminal and try again.' }

    $v = Invoke-Process -FilePath $path -ArgumentList @('--version') -TimeoutSeconds 60
    $WinGetState.Version = ($v.Output -replace '[^\d\.]', '').Trim('.')
    $flags = @('--accept-source-agreements')
    $modern = $true
    if ($WinGetState.Version -match '^(\d+)\.(\d+)') {
        if ([int]$Matches[1] -lt 1 -or ([int]$Matches[1] -eq 1 -and [int]$Matches[2] -lt 4)) { $modern = $false }
    }
    if ($modern) { $flags += '--disable-interactivity' } else { Write-Warn 'Old winget version - running without --disable-interactivity.' }
    $WinGetState.Flags = $flags
    $WinGetState.Ready = $true
    Write-Ok ("WinGet {0} ({1})" -f $WinGetState.Version, $path)
    return $path
}

function Install-WinGet {
    <# Menu item: install or repair WinGet via asheroto's winget-install script. #>
    param([switch]$Force)
    Write-Title 'WinGet'
    if ((Get-WinGetPath) -and -not $Force) {
        $null = Initialize-WinGet
        Write-Ok 'WinGet is already installed.'
        return
    }
    Invoke-RemoteScript -Url $Urls.WinGetInstall -Name 'winget-install (asheroto)'
    Update-SessionPath
    $WinGetState.Path = $null; $WinGetState.Ready = $false
    if (-not (Get-WinGetPath)) { throw 'WinGet is still not available in this session. Open a new terminal and try again.' }
    $null = Initialize-WinGet
    Write-Ok 'WinGet ready.'
}

function Update-WinGetSources {
    $r = Invoke-Process -FilePath (Initialize-WinGet) -ArgumentList (@('source', 'update') + $WinGetState.Flags) -TimeoutSeconds 300
    if ($r.Code -ne 0) { Write-Warn 'Could not refresh winget sources - continuing with the cached state.' }
}

function Test-WinGetInstalled {
    <# $true when the package is installed. In doubt returns $false - installing once too often beats silently skipping. #>
    param([Parameter(Mandatory)][string]$Id)
    $r = Invoke-Process -FilePath (Initialize-WinGet) -ArgumentList (@('list', '--exact', '--id', $Id) + $WinGetState.Flags) -TimeoutSeconds 120
    if ($r.Code -ne 0) { return $false }
    if ([string]::IsNullOrWhiteSpace($r.Output)) { return $false }
    if ($r.Output -match 'No installed package') { return $false }
    return $true
}

function Get-WinGetCodeText {
    param([int]$Code)
    switch ($Code) {
        0           { 'success' }
        3010        { 'success, reboot required' }
        1602        { 'cancelled by user' }
        1603        { 'fatal installer error' }
        1618        { 'another installation is running' }
        1641        { 'success, reboot initiated' }
        -999        { 'timeout' }
        -998        { 'process could not be started' }
        -1978335189 { 'no applicable update found' }
        -1978335212 { 'package not found' }
        default     { '0x{0:X8}' -f $Code }
    }
}

function Install-WinGetPackage {
    <#
    .SYNOPSIS
        Installs (or upgrades) one package robustly and prints a one-line result.
    .DESCRIPTION
        Checks the real installation state first, then tries winget with several call variants
        (machine scope -> user scope -> no source pinning), retries with back-off, and finally
        verifies by winget list - exit codes differ between winget versions and are not trusted.
        Returns [pscustomobject]@{ Status = Installed|Upgraded|Present|Failed|DryRun; Code; Note; Variant }.
    .PARAMETER Upgrade
        Also upgrade when already installed (default: leave installed packages alone).
    .PARAMETER DryRun
        Only report what would happen.
    .PARAMETER Source
        Restrict to one winget source (e.g. msstore). Default: winget source with fallbacks.
    #>
    param(
        [Parameter(Mandatory)][string]$Id,
        [string]$Name = $Id,
        [string]$Source,
        [switch]$Upgrade,
        [switch]$DryRun,
        [int]$Retries = 2,
        [int]$TimeoutMinutes = 20
    )
    $winget = Initialize-WinGet
    $label = "   {0,-42} " -f $Name
    $present = Test-WinGetInstalled -Id $Id

    if ($present -and -not $Upgrade) {
        Write-Host $label -NoNewline; Write-Host 'present' -ForegroundColor DarkGreen
        Write-LogLine "$Name ($Id): present"
        return [pscustomobject]@{ Status = 'Present'; Code = 0; Note = ''; Variant = '' }
    }
    if ($DryRun) {
        $what = if ($present) { 'would upgrade' } else { 'would install' }
        Write-Host $label -NoNewline; Write-Host $what -ForegroundColor Cyan
        return [pscustomobject]@{ Status = 'DryRun'; Code = 0; Note = $what; Variant = '' }
    }

    $verb = if ($present) { 'upgrade' } else { 'install' }
    $base = @($verb, '--exact', '--id', $Id, '--silent', '--accept-package-agreements') + $WinGetState.Flags
    if ($Source) {
        $variants = @(@{ Text = $Source; Args = $base + @('--source', $Source) })
    } else {
        $variants = @(
            @{ Text = 'machine scope'; Args = $base + @('--source', 'winget', '--scope', 'machine') },
            @{ Text = 'user scope';    Args = $base + @('--source', 'winget') },
            @{ Text = 'any source';    Args = $base }
        )
    }
    Write-Host $label -NoNewline
    Write-Host ("{0}..." -f $verb) -ForegroundColor DarkGray -NoNewline

    $last = $null
    $stop = $false
    for ($round = 0; $round -le $Retries -and -not $stop; $round++) {
        if ($round -gt 0) { Start-Sleep -Seconds (5 * $round) }
        foreach ($v in $variants) {
            $r = Invoke-Process -FilePath $winget -ArgumentList $v.Args -TimeoutSeconds ($TimeoutMinutes * 60)
            $last = $r
            Write-LogLine ("{0} ({1}): winget {2} [{3}] -> {4} ({5})" -f $Name, $Id, $verb, $v.Text, $r.Code, (Get-WinGetCodeText $r.Code))
            if ($r.Code -eq 0) {
                $status = if ($present) { 'Upgraded' } else { 'Installed' }
                Write-Host ("`r" + $label) -NoNewline; Write-Host $status.ToLower() -ForegroundColor Green
                return [pscustomobject]@{ Status = $status; Code = 0; Note = ''; Variant = $v.Text }
            }
            if ($r.Code -eq 3010 -or $r.Code -eq 1641) {
                Write-Host ("`r" + $label) -NoNewline; Write-Host 'installed, reboot required' -ForegroundColor Green
                return [pscustomobject]@{ Status = 'Installed'; Code = $r.Code; Note = 'reboot required'; Variant = $v.Text }
            }
            if ($r.Code -eq -1978335189 -and $present) {
                Write-Host ("`r" + $label) -NoNewline; Write-Host 'up to date' -ForegroundColor DarkGreen
                return [pscustomobject]@{ Status = 'Present'; Code = $r.Code; Note = 'no update available'; Variant = '' }
            }
            if ($r.Code -eq 1618) { break }          # another installer is running - wait, do not switch variants
            if ($r.TimedOut) { $stop = $true; break } # a hanging installer hangs again - do not burn more timeouts
        }
    }

    # last resort: did it work despite the error code?
    if (Test-WinGetInstalled -Id $Id) {
        if ($present) {
            Write-Host ("`r" + $label) -NoNewline; Write-Host ("present (upgrade failed: {0})" -f (Get-WinGetCodeText $last.Code)) -ForegroundColor Yellow
            return [pscustomobject]@{ Status = 'Present'; Code = $last.Code; Note = 'upgrade failed'; Variant = '' }
        }
        Write-Host ("`r" + $label) -NoNewline; Write-Host ("installed (winget reported {0})" -f (Get-WinGetCodeText $last.Code)) -ForegroundColor Green
        return [pscustomobject]@{ Status = 'Installed'; Code = $last.Code; Note = 'present despite error code'; Variant = '' }
    }
    $short = ''
    if ($last -and $last.Output) { $short = (($last.Output -split "`r?`n" | Where-Object { $_.Trim() } | Select-Object -Last 2) -join ' / ') }
    Write-Host ("`r" + $label) -NoNewline; Write-Host ("FAILED ({0})" -f (Get-WinGetCodeText $last.Code)) -ForegroundColor Red
    if ($short) { Write-Host ("      {0}" -f $short) -ForegroundColor DarkGray }
    return [pscustomobject]@{ Status = 'Failed'; Code = $last.Code; Note = $short; Variant = '' }
}

function Install-WindowsFeatureItem {
    <# Enables a Windows optional feature (e.g. NetFx3). Same result object as Install-WinGetPackage. #>
    param([Parameter(Mandatory)][string]$FeatureName, [string]$Name = $FeatureName, [switch]$DryRun)
    $label = "   {0,-42} " -f $Name
    try { $f = Get-WindowsOptionalFeature -Online -FeatureName $FeatureName -ErrorAction Stop }
    catch {
        Write-Host $label -NoNewline; Write-Host "FAILED (cannot query: $($_.Exception.Message))" -ForegroundColor Red
        return [pscustomobject]@{ Status = 'Failed'; Code = -1; Note = $_.Exception.Message; Variant = '' }
    }
    if ($f.State -eq 'Enabled') {
        Write-Host $label -NoNewline; Write-Host 'present' -ForegroundColor DarkGreen
        return [pscustomobject]@{ Status = 'Present'; Code = 0; Note = ''; Variant = '' }
    }
    if ($DryRun) {
        Write-Host $label -NoNewline; Write-Host 'would enable' -ForegroundColor Cyan
        return [pscustomobject]@{ Status = 'DryRun'; Code = 0; Note = 'would enable'; Variant = '' }
    }
    try {
        $r = Enable-WindowsOptionalFeature -Online -FeatureName $FeatureName -All -NoRestart -ErrorAction Stop
        $note = if ($r.RestartNeeded) { 'reboot required' } else { '' }
        Write-Host $label -NoNewline; Write-Host 'enabled' -ForegroundColor Green
        return [pscustomobject]@{ Status = 'Installed'; Code = 0; Note = $note; Variant = '' }
    } catch {
        Write-Host $label -NoNewline; Write-Host "FAILED ($($_.Exception.Message))" -ForegroundColor Red
        Write-Host '      Common cause: Windows Update blocked by policy (WSUS) - needs install media as source.' -ForegroundColor DarkGray
        return [pscustomobject]@{ Status = 'Failed'; Code = -1; Note = $_.Exception.Message; Variant = '' }
    }
}

# ---------------------------------------------------------------------------
# tools/adwcleaner.ps1 - download, run and remove Malwarebytes AdwCleaner.
# ---------------------------------------------------------------------------

function Invoke-AdwCleaner {
    <#
    .SYNOPSIS
        Downloads AdwCleaner to %TEMP%, runs it interactively and deletes it afterwards.
    .NOTES
        AdwCleaner asks for elevation itself, so this tool does not need an admin shell.
    #>
    Write-Title 'Malwarebytes AdwCleaner'
    $exe = Join-Path ([IO.Path]::GetTempPath()) 'adwcleaner.exe'
    try {
        Write-Step 'Downloading the latest AdwCleaner...'
        Get-RemoteFile -Uri $Urls.AdwCleaner -OutFile $exe
        Write-Ok "Saved to $exe"

        Write-Step 'Starting AdwCleaner - close it when you are done.'
        Start-Process -FilePath $exe -Wait
        Write-Ok 'AdwCleaner finished.'
    } finally {
        if (Test-Path $exe) {
            Remove-Item $exe -Force -ErrorAction SilentlyContinue
            Write-Ok 'Temporary file removed.'
        }
    }
}

# ---------------------------------------------------------------------------
# tools/windows-update.ps1 - install all pending Windows updates via PSWindowsUpdate.
# ---------------------------------------------------------------------------

function Invoke-WindowsUpdate {
    <#
    .SYNOPSIS
        Installs the PSWindowsUpdate module if needed, then installs every available update.
    .PARAMETER NoReboot
        Do not reboot automatically when an update requires it.
    .NOTES
        Requires an elevated shell.
    #>
    param([switch]$NoReboot)

    Write-Title 'Windows Update (PSWindowsUpdate)'
    if (-not (Test-IsAdmin)) { throw 'Administrator rights are required for Windows Update.' }

    Write-Step 'Checking NuGet package provider...'
    if (Get-PackageProvider -Name NuGet -ListAvailable -ErrorAction SilentlyContinue) {
        Write-Ok 'NuGet provider present.'
    } else {
        Write-Step 'Installing NuGet package provider...'
        $null = Install-PackageProvider -Name NuGet -MinimumVersion 2.8.5.201 -Force
    }

    Write-Step 'Checking PSWindowsUpdate module...'
    if (Get-Module -ListAvailable -Name PSWindowsUpdate) {
        Write-Ok 'PSWindowsUpdate present.'
    } else {
        Write-Step 'Installing PSWindowsUpdate from the PowerShell Gallery...'
        Install-Module -Name PSWindowsUpdate -Force
    }
    Import-Module PSWindowsUpdate

    Write-Step 'Searching for updates...'
    $updates = @(Get-WindowsUpdate)
    if ($updates.Count -eq 0) {
        Write-Ok 'No updates available - system is up to date.'
        return
    }
    $updates | Format-Table -AutoSize KB, Size, Title | Out-String | Write-Host

    Write-Step "Installing $($updates.Count) update(s)..."
    if ($NoReboot) {
        Get-WindowsUpdate -Install -AcceptAll -IgnoreReboot
    } else {
        Write-Warn 'The system will reboot automatically if an update requires it.'
        Get-WindowsUpdate -Install -AcceptAll -AutoReboot
    }
    Write-Ok 'Windows Update finished.'
}

# ---------------------------------------------------------------------------
# tools/software.ps1 - Software Setup: profiles + catalog of winget packages.
# English port of Install-Software.ps1 (the PC-Gaming-Redists successor): pick profiles
# (Runtimes / Standard / Gaming / Technician), browse categories, search, save/load a
# selection, dry run, then install with the robust winget engine from common.ps1.
# The catalog (catalog/software.json) is embedded into dist/ by build.ps1 as $CatalogJson.
# ---------------------------------------------------------------------------

$SoftwareState = @{ Catalog = $null; Selected = $null; Upgrade = $false; DryRun = $false }

function Get-SoftwareCatalog {
    if ($SoftwareState.Catalog) { return $SoftwareState.Catalog }
    $json = $CatalogJson
    if (-not $json) {
        # running from src/ (development, tests): read the repo file
        $file = Join-Path $PSScriptRoot '..\..\catalog\software.json'
        if (-not (Test-Path -LiteralPath $file)) { throw "Catalog not found: $file" }
        $json = Get-Content -LiteralPath $file -Raw -Encoding UTF8
    }
    try { $cat = $json | ConvertFrom-Json } catch { throw "Catalog is not valid JSON: $($_.Exception.Message)" }
    foreach ($field in 'apps', 'categories', 'profiles') {
        if (-not ($cat.PSObject.Properties.Name -contains $field)) { throw "Catalog has no '$field' field." }
    }
    $dupes = @($cat.apps | Group-Object key | Where-Object Count -gt 1)
    if ($dupes.Count -gt 0) { throw ("Duplicate keys in catalog: {0}" -f (($dupes | Select-Object -First 5).Name -join ', ')) }
    $SoftwareState.Catalog = $cat
    return $cat
}

function Get-SoftwareSelection {
    if (-not $SoftwareState.Selected) {
        $SoftwareState.Selected = New-Object 'System.Collections.Generic.HashSet[string]' -ArgumentList ([StringComparer]::OrdinalIgnoreCase)
    }
    return ,$SoftwareState.Selected   # comma: do not enumerate the HashSet on output
}

function Get-SoftwareProfileNames {
    param($Catalog)
    return @($Catalog.profiles.PSObject.Properties | ForEach-Object Name)
}

function Add-SoftwareProfile {
    param($Catalog, [Parameter(Mandatory)][string]$Name)
    $sel = Get-SoftwareSelection
    $p = $Catalog.profiles.PSObject.Properties[$Name]
    if (-not $p) { throw "Unknown profile '$Name'. Available: $((Get-SoftwareProfileNames $Catalog) -join ', ')" }
    foreach ($k in $p.Value.apps) { [void]$sel.Add($k) }
}

function Expand-NumberList {
    # "1 3 5-9" -> 1,3,5,6,7,8,9 (bounded by 1..Max)
    param([string]$Text, [int]$Max)
    $out = New-Object 'System.Collections.Generic.List[int]'
    foreach ($part in ($Text -split '[,\s]+' | Where-Object { $_ })) {
        if ($part -match '^(\d+)-(\d+)$') {
            $a = [int]$Matches[1]; $b = [int]$Matches[2]
            if ($a -gt $b) { $t = $a; $a = $b; $b = $t }
            for ($i = $a; $i -le $b; $i++) { if ($i -ge 1 -and $i -le $Max) { $out.Add($i) } }
        } elseif ($part -match '^\d+$') {
            $i = [int]$part
            if ($i -ge 1 -and $i -le $Max) { $out.Add($i) }
        }
    }
    return ,$out
}

function Show-NumberedList {
    # numbered list with [x] marks, two columns from 24 entries on
    param($Items, $Selected)
    $n = $Items.Count
    $cols = if ($n -gt 24) { 2 } else { 1 }
    $rows = [math]::Ceiling($n / $cols)
    $width = 34
    for ($r = 0; $r -lt $rows; $r++) {
        $line = ''
        for ($c = 0; $c -lt $cols; $c++) {
            $i = $r + ($c * $rows)
            if ($i -ge $n) { continue }
            $e = $Items[$i]
            $mark = if ($Selected.Contains($e.key)) { 'x' } else { ' ' }
            $text = $e.name
            if ($text.Length -gt $width) { $text = $text.Substring(0, $width - 1) + '.' }
            $line += ('  [{0}] {1,3}. {2,-' + $width + '}') -f $mark, ($i + 1), $text
        }
        Write-Host $line
    }
}

function Show-SoftwareCategory {
    param($Catalog, [string]$Category)
    $sel = Get-SoftwareSelection
    $items = @($Catalog.apps | Where-Object { $_.category -eq $Category } | Sort-Object name)
    while ($true) {
        Clear-Host
        $chosen = @($items | Where-Object { $sel.Contains($_.key) }).Count
        Write-Title ("{0}  ({1} packages, {2} selected)" -f $Category, $items.Count, $chosen)
        Write-Host ''
        Show-NumberedList -Items $items -Selected $sel
        Write-Host ''
        Write-Host '  Toggle numbers (e.g. 1 4 7-9)   [a] all   [n] none   [i <nr>] info   [Enter] back' -ForegroundColor DarkGray
        $e = Read-MenuLine
        if ($e -eq '') { return }
        if ($e -eq 'a') { foreach ($x in $items) { [void]$sel.Add($x.key) }; continue }
        if ($e -eq 'n') { foreach ($x in $items) { [void]$sel.Remove($x.key) }; continue }
        if ($e -match '^i\s+(\d+)$') {
            $i = [int]$Matches[1]
            if ($i -ge 1 -and $i -le $items.Count) {
                $a = $items[$i - 1]
                Write-Host ''
                Write-Host ("  {0}" -f $a.name) -ForegroundColor White
                Write-Host ("  winget id : {0}" -f $(if ($a.type -eq 'feature') { "Windows feature $($a.feature)" } else { $a.id })) -ForegroundColor DarkGray
                if ($a.link) { Write-Host ("  website   : {0}" -f $a.link) -ForegroundColor DarkGray }
                if ($a.info) { Write-Host ("  info      : {0}" -f $a.info) -ForegroundColor DarkGray }
                Write-Host ''
                $null = Read-MenuLine '  Enter to continue'
            }
            continue
        }
        foreach ($i in (Expand-NumberList -Text $e -Max $items.Count)) {
            $k = $items[$i - 1].key
            if ($sel.Contains($k)) { [void]$sel.Remove($k) } else { [void]$sel.Add($k) }
        }
    }
}

function Show-SoftwareSearch {
    param($Catalog)
    $sel = Get-SoftwareSelection
    $term = Read-MenuLine '  Search'
    if (-not $term) { return }
    $hits = @($Catalog.apps | Where-Object { $_.name -like "*$term*" -or $_.id -like "*$term*" -or $_.key -like "*$term*" } | Sort-Object category, name)
    if ($hits.Count -eq 0) {
        Write-Warn "Nothing found for '$term'."
        $null = Read-MenuLine '  Enter to continue'
        return
    }
    while ($true) {
        Clear-Host
        Write-Title ("Search '{0}' - {1} hits" -f $term, $hits.Count)
        Write-Host ''
        for ($i = 0; $i -lt $hits.Count; $i++) {
            $e = $hits[$i]
            $mark = if ($sel.Contains($e.key)) { 'x' } else { ' ' }
            Write-Host ('  [{0}] {1,3}. {2,-36} {3}' -f $mark, ($i + 1), $e.name, $e.category)
        }
        Write-Host ''
        Write-Host '  Toggle numbers   [a] all   [Enter] back' -ForegroundColor DarkGray
        $e = Read-MenuLine
        if ($e -eq '') { return }
        if ($e -eq 'a') { foreach ($x in $hits) { [void]$sel.Add($x.key) }; continue }
        foreach ($i in (Expand-NumberList -Text $e -Max $hits.Count)) {
            $k = $hits[$i - 1].key
            if ($sel.Contains($k)) { [void]$sel.Remove($k) } else { [void]$sel.Add($k) }
        }
    }
}

function Get-SelectionFolder {
    $dir = Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'win-toolbox'
    if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    return $dir
}

function Save-SoftwareSelection {
    $sel = Get-SoftwareSelection
    $name = Read-MenuLine '  File name (Enter = selection.json)'
    if (-not $name) { $name = 'selection.json' }
    if ($name -notlike '*.json') { $name += '.json' }
    $path = if ([IO.Path]::IsPathRooted($name)) { $name } else { Join-Path (Get-SelectionFolder) $name }
    if ((Test-Path -LiteralPath $path) -and -not (Confirm-Action "  $([IO.Path]::GetFileName($path)) exists. Overwrite?")) { return }
    try {
        [pscustomobject]@{ created = (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'); host = $env:COMPUTERNAME; apps = @($sel) } |
            ConvertTo-Json -Depth 4 | Set-Content -LiteralPath $path -Encoding UTF8
        Write-Ok "Saved: $path"
    } catch { Write-Fail "Save failed: $($_.Exception.Message)" }
    $null = Read-MenuLine '  Enter to continue'
}

function Import-SoftwareSelection {
    <# Loads a saved selection from a local file or a URL (e.g. a gist raw link). #>
    param($Catalog, [string]$Source)
    $sel = Get-SoftwareSelection
    if (-not $Source) {
        $files = @(Get-ChildItem -LiteralPath (Get-SelectionFolder) -Filter '*.json' -ErrorAction SilentlyContinue)
        for ($i = 0; $i -lt $files.Count; $i++) { Write-Host ('    [{0}] {1}' -f ($i + 1), $files[$i].Name) }
        if ($files.Count -eq 0) { Write-Host ('    (no saved selections in {0})' -f (Get-SelectionFolder)) -ForegroundColor DarkGray }
        $Source = Read-MenuLine '  Number, path or URL'
        if ($Source -match '^\d+$' -and [int]$Source -ge 1 -and [int]$Source -le $files.Count) { $Source = $files[[int]$Source - 1].FullName }
        if (-not $Source) { return }
    }
    try {
        $json = if ($Source -match '^https?://') { Invoke-RestMethod -Uri $Source -UseBasicParsing } else { Get-Content -LiteralPath $Source -Raw -Encoding UTF8 }
        $obj = if ($json -is [string]) { $json | ConvertFrom-Json } else { $json }
        if (-not ($obj.PSObject.Properties.Name -contains 'apps')) { throw 'selection file has no "apps" field (expected {"apps":["7zip","vlc"]})' }
        $known = @{}; foreach ($a in $Catalog.apps) { $known[$a.key] = $true }
        $unknown = @($obj.apps | Where-Object { -not $known.ContainsKey($_) })
        $sel.Clear()
        foreach ($k in $obj.apps) { if ($known.ContainsKey($k)) { [void]$sel.Add($k) } }
        Write-Ok ("{0} packages loaded." -f $sel.Count)
        if ($unknown.Count -gt 0) { Write-Warn ("Ignored unknown keys: {0}" -f ($unknown -join ', ')) }
    } catch { Write-Fail "Load failed: $($_.Exception.Message)" }
    $null = Read-MenuLine '  Enter to continue'
}

function Show-SoftwareSelection {
    param($Catalog)
    $sel = Get-SoftwareSelection
    Clear-Host
    Write-Title ("Selected: {0} packages" -f $sel.Count)
    $Catalog.apps | Where-Object { $sel.Contains($_.key) } | Sort-Object category, name |
        Format-Table @{ L = 'Category'; E = { $_.category } }, @{ L = 'Name'; E = { $_.name } }, @{ L = 'winget id'; E = { $_.id } } -AutoSize |
        Out-String -Width 120 | Write-Host
    $null = Read-MenuLine '  Enter to continue'
}

function Show-SoftwareMenu {
    <# Returns $true when the user wants to install the current selection, $false to go back. #>
    param($Catalog)
    $sel = Get-SoftwareSelection
    $profiles = Get-SoftwareProfileNames $Catalog
    $cats = @($Catalog.categories)
    while ($true) {
        Clear-Host
        Write-Title 'Software Setup'
        Write-Host ("   Catalog  : {0} packages, updated {1}" -f @($Catalog.apps).Count, $Catalog.updated) -ForegroundColor DarkGray
        Write-Host ("   Selected : {0} packages" -f $sel.Count) -ForegroundColor $(if ($sel.Count) { 'Green' } else { 'Yellow' })
        Write-Host ("   Mode     : {0}{1}" -f $(if ($SoftwareState.Upgrade) { 'install missing + upgrade present' } else { 'install missing only' }),
                                              $(if ($SoftwareState.DryRun) { '   [DRY RUN - nothing is installed]' } else { '' })) -ForegroundColor DarkGray
        Write-Host ''
        Write-Host '   Profiles (add to selection):'
        for ($i = 0; $i -lt $profiles.Count; $i++) {
            $p = $Catalog.profiles.PSObject.Properties[$profiles[$i]].Value
            Write-Host ('     [{0,2}] {1,-12} {2,3} pkgs   {3}' -f ($i + 1), $profiles[$i], @($p.apps).Count, $p.description)
        }
        Write-Host ''
        Write-Host '   Categories (browse and toggle single packages):'
        for ($i = 0; $i -lt $cats.Count; $i++) {
            $all = @($Catalog.apps | Where-Object { $_.category -eq $cats[$i] })
            $chosen = @($all | Where-Object { $sel.Contains($_.key) }).Count
            Write-Host ('     [{0,2}] {1,-22} {2,3} pkgs{3}' -f ($profiles.Count + $i + 1), $cats[$i], $all.Count, $(if ($chosen) { "   ($chosen selected)" } else { '' }))
        }
        Write-Host ''
        Write-Host '     [s] search      [v] view selection   [x] clear selection'
        Write-Host '     [u] toggle upgrade mode              [d] toggle dry run'
        Write-Host '     [l] load selection (file/URL)        [w] save selection'
        Write-Host ''
        Write-Host '     [Enter] install selection            [q] back' -ForegroundColor Green
        Write-Host ''
        $e = (Read-MenuLine '  Choice').ToLower()

        if ($e -eq '') {
            if ($sel.Count -eq 0) { Write-Warn 'Nothing selected.'; Start-Sleep -Seconds 1; continue }
            return $true
        }
        switch -Regex ($e) {
            '^q$' { return $false }
            '^s$' { Show-SoftwareSearch -Catalog $Catalog; break }
            '^v$' { Show-SoftwareSelection -Catalog $Catalog; break }
            '^x$' { $sel.Clear(); break }
            '^u$' { $SoftwareState.Upgrade = -not $SoftwareState.Upgrade; break }
            '^d$' { $SoftwareState.DryRun = -not $SoftwareState.DryRun; break }
            '^l$' { Import-SoftwareSelection -Catalog $Catalog; break }
            '^w$' { Save-SoftwareSelection; break }
            '^\d+$' {
                $i = [int]$e
                if ($i -ge 1 -and $i -le $profiles.Count) { Add-SoftwareProfile -Catalog $Catalog -Name $profiles[$i - 1] }
                elseif ($i -gt $profiles.Count -and $i -le ($profiles.Count + $cats.Count)) { Show-SoftwareCategory -Catalog $Catalog -Category $cats[$i - $profiles.Count - 1] }
                break
            }
        }
    }
}

function Invoke-SoftwareInstall {
    <# Installs the current selection; returns the result objects. #>
    param($Catalog)
    $sel = Get-SoftwareSelection
    $list = @($Catalog.apps | Where-Object { $sel.Contains($_.key) } |
              Sort-Object @{ E = { if ($_.category -eq 'Runtimes') { 0 } else { 1 } } }, category, name)
    if ($list.Count -eq 0) { Write-Warn 'Nothing selected.'; return @() }
    if (-not (Test-IsAdmin)) { throw 'Administrator rights are required to install software.' }

    $log = Start-Log -Name 'software-setup'
    Write-Title ("Installing {0} packages{1}" -f $list.Count, $(if ($SoftwareState.DryRun) { ' (dry run)' } else { '' }))
    Write-LogLine ("selection: {0}" -f (($list | ForEach-Object key) -join ' '))

    if (@($list | Where-Object { $_.type -eq 'winget' }).Count -gt 0) {
        $null = Initialize-WinGet
        if (-not $SoftwareState.DryRun) { Update-WinGetSources }
    }
    $results = New-Object 'System.Collections.Generic.List[object]'
    $start = Get-Date
    $n = 0
    foreach ($app in $list) {
        $n++
        Write-Host ("`n  [{0}/{1}] {2}" -f $n, $list.Count, $app.category) -ForegroundColor DarkGray
        try {
            if ($app.type -eq 'feature') { $r = Install-WindowsFeatureItem -FeatureName $app.feature -Name $app.name -DryRun:$SoftwareState.DryRun }
            else { $r = Install-WinGetPackage -Id $app.id -Name $app.name -Upgrade:$SoftwareState.Upgrade -DryRun:$SoftwareState.DryRun }
        } catch {
            Write-Fail ("{0} - unexpected error: {1}" -f $app.name, $_.Exception.Message)
            $r = [pscustomobject]@{ Status = 'Failed'; Code = -997; Note = $_.Exception.Message; Variant = '' }
        }
        $results.Add([pscustomobject]@{ Category = $app.category; Key = $app.key; Name = $app.name; Id = $app.id; Status = $r.Status; Code = $r.Code; Note = $r.Note; Variant = $r.Variant })
    }
    Write-SoftwareReport -Results $results -Duration ((Get-Date) - $start) -LogPath $log
    return ,$results
}

function Write-SoftwareReport {
    param($Results, [timespan]$Duration, [string]$LogPath)
    Write-Title 'Summary'
    foreach ($g in ($Results | Group-Object Status | Sort-Object Name)) {
        $color = switch ($g.Name) { 'Failed' { 'Red' } 'Present' { 'DarkGray' } default { 'Green' } }
        Write-Host ('   {0,-10} {1,3}' -f $g.Name, $g.Count) -ForegroundColor $color
    }
    $userScope = @($Results | Where-Object { $_.Variant -and $_.Variant -ne 'machine scope' -and $_.Variant -ne 'msstore' })
    if ($userScope.Count -gt 0) {
        Write-Host ''
        Write-Host '   Installed without enforced machine scope (package does not support it):' -ForegroundColor Yellow
        foreach ($u in $userScope) { Write-Host ('     - {0}' -f $u.Name) -ForegroundColor Yellow }
        Write-Host '     Whether they apply to all users is up to the installer.' -ForegroundColor DarkGray
    }
    $failed = @($Results | Where-Object Status -eq 'Failed')
    if ($failed.Count -gt 0) {
        Write-Host ''
        Write-Host '   Not installed:' -ForegroundColor Red
        foreach ($f in $failed) { Write-Host ('     - {0,-34} {1}' -f $f.Name, $f.Note) -ForegroundColor Red }
        Write-Host '   Retry single packages with:' -ForegroundColor DarkGray
        foreach ($f in ($failed | Where-Object Id | Select-Object -First 5)) { Write-Host ('     winget install --exact --id {0}' -f $f.Id) -ForegroundColor DarkGray }
    }
    if (@($Results | Where-Object { $_.Note -like '*reboot*' }).Count -gt 0) {
        Write-Host ''
        Write-Host '   At least one package needs a reboot to take effect.' -ForegroundColor Yellow
    }
    if ($LogPath) {
        $csv = [IO.Path]::ChangeExtension($LogPath, 'csv')
        try {
            $Results | Select-Object @{ L = 'Timestamp'; E = { Get-Date -Format 'yyyy-MM-dd HH:mm:ss' } }, @{ L = 'Host'; E = { $env:COMPUTERNAME } },
                Category, Name, Id, Status, Code, Variant, Note |
                Export-Csv -LiteralPath $csv -NoTypeInformation -Delimiter ';' -Encoding UTF8
            Write-Host ''
            Write-Host ("   Report : {0}" -f $csv) -ForegroundColor DarkGray
        } catch { Write-Warn "CSV report could not be written: $($_.Exception.Message)" }
        Write-Host ("   Log    : {0}" -f $LogPath) -ForegroundColor DarkGray
    }
    Write-Host ("   Took   : {0:hh\:mm\:ss}" -f $Duration) -ForegroundColor DarkGray
}

function Invoke-SoftwareSetup {
    <#
    .SYNOPSIS
        Menu-driven software installation from the embedded catalog (profiles, categories, search).
    .PARAMETER ProfileName
        Pre-select a profile (Runtimes, Standard, Gaming, Technician).
    #>
    param([string]$ProfileName)
    $cat = Get-SoftwareCatalog
    if ($ProfileName) { Add-SoftwareProfile -Catalog $cat -Name $ProfileName }
    while (Show-SoftwareMenu -Catalog $cat) {
        $null = Invoke-SoftwareInstall -Catalog $cat
        Wait-AnyKey 'Press any key to return to the Software Setup menu...'
    }
}

# ---------------------------------------------------------------------------
# tools/inventory.ps1 - hardware, OS and software inventory -> CSV.
# English port of Inventar-Windows.ps1 (technician stick). The CSV SCHEMA STAYS GERMAN on
# purpose (Zeitstempel;Hostname;Kategorie;Feld;Wert, Inventar_Uebersicht.csv columns,
# UTF-8 BOM + CRLF): it is shared with inventar-linux.sh and existing collections. Only the
# console UI is English. Do not rename fields/values in the data without changing the Linux twin.
# ---------------------------------------------------------------------------

$InventoryState = @{
    OutputMode = 'Desktop'      # Desktop | CurrentDir | Custom
    OutputPath = ''
    Delimiter  = ';'
    Comment    = ''
    Summary    = $true
    Software   = 'all'          # all | noupdates | none
    Detail     = $false
}

function Get-InventoryOutputPath {
    switch ($InventoryState.OutputMode) {
        'CurrentDir' { return (Get-Location).Path }
        'Custom'     { if ($InventoryState.OutputPath) { return $InventoryState.OutputPath } }
    }
    $desktop = [Environment]::GetFolderPath('Desktop')
    if (-not $desktop) { $desktop = (Get-Location).Path }
    return $desktop
}

function Select-FolderDialog {
    # Folder picker seam (replaced by tests). Returns path or $null.
    param([string]$Description = 'Select the output folder')
    try {
        Add-Type -AssemblyName System.Windows.Forms
        $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
        $dlg.Description = $Description
        $dlg.ShowNewFolderButton = $true
        if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { return $dlg.SelectedPath }
    } catch { Write-Warn "Folder dialog not available: $($_.Exception.Message)" }
    return $null
}

function Show-InventoryMenu {
    <# Returns $true to start, $false to go back. #>
    while ($true) {
        Clear-Host
        Write-Title 'Inventory'
        Write-Host '   Collects hardware, BIOS/TPM, OS, CPU, RAM, disks, GPU, monitors, network, battery and' -ForegroundColor DarkGray
        Write-Host '   installed software into CSV files (German schema, compatible with inventar-linux.sh).' -ForegroundColor DarkGray
        Write-Host ''
        $modeText = switch ($InventoryState.OutputMode) { 'Desktop' { 'Desktop' } 'CurrentDir' { 'current directory' } 'Custom' { 'custom folder' } }
        Write-Host ("   [1] Output folder   : {0}  ({1})" -f (Get-InventoryOutputPath), $modeText)
        Write-Host ("   [2] CSV delimiter   : {0}" -f $(if ($InventoryState.Delimiter -eq "`t") { 'TAB' } else { $InventoryState.Delimiter }))
        Write-Host ("   [3] Comment         : {0}" -f $(if ($InventoryState.Comment) { $InventoryState.Comment } else { '(none)' }))
        Write-Host ("   [4] Append overview : {0}" -f $(if ($InventoryState.Summary) { 'yes (Inventar_Uebersicht.csv)' } else { 'no' }))
        Write-Host ("   [5] Rights          : {0}" -f $(if (Test-IsAdmin) { 'administrator' } else { 'standard user - [5] relaunches elevated (TPM, battery, RAM modules need admin)' }))
        Write-Host ("   [6] Software        : {0}" -f $(switch ($InventoryState.Software) { 'all' { 'programs, store apps and Windows updates' } 'noupdates' { 'programs and store apps, no Windows updates' } 'none' { 'not collected' } }))
        Write-Host ("   [7] Software detail : {0}" -f $(if ($InventoryState.Detail) { 'yes - every program as a row in the detail CSV' } else { 'no - counts only' }))
        Write-Host ''
        Write-Host '   [Enter] start inventory        [q] back' -ForegroundColor Green
        Write-Host ''
        $e = (Read-MenuLine '  Choice').ToLower()
        switch ($e) {
            ''  { return $true }
            's' { return $true }
            'q' { return $false }
            '1' {
                Write-Host ''
                Write-Host '     [1] Desktop   [2] current directory   [3] pick a folder'
                $m = Read-MenuLine '  Output folder'
                switch ($m) {
                    '1' { $InventoryState.OutputMode = 'Desktop' }
                    '2' { $InventoryState.OutputMode = 'CurrentDir' }
                    '3' { $p = Select-FolderDialog; if ($p) { $InventoryState.OutputMode = 'Custom'; $InventoryState.OutputPath = $p } }
                }
            }
            '2' {
                $d = Read-MenuLine "  Delimiter - ';' , ',' or 'TAB' (Enter = unchanged)"
                if ($d) {
                    if ($d.ToUpper() -eq 'TAB') { $InventoryState.Delimiter = "`t" }
                    elseif ($d.Length -eq 1) { $InventoryState.Delimiter = $d }
                    else { Write-Warn 'The delimiter must be exactly one character.'; Start-Sleep -Seconds 1 }
                }
            }
            '3' { $InventoryState.Comment = Read-MenuLine '  Comment (e.g. loan device company XY, invoice 1234)' }
            '4' { $InventoryState.Summary = -not $InventoryState.Summary }
            '5' {
                if (Test-IsAdmin) { Write-Warn 'Already running as administrator.'; Start-Sleep -Seconds 1 }
                elseif (Invoke-Elevated -SelfUrl $SelfUrl) { Write-Warn 'Elevated window started - settings start fresh there.'; Start-Sleep -Seconds 2; return $false }
            }
            '6' {
                $InventoryState.Software = switch ($InventoryState.Software) { 'all' { 'noupdates' } 'noupdates' { 'none' } default { 'all' } }
            }
            '7' { $InventoryState.Detail = -not $InventoryState.Detail }
        }
    }
}

function Update-CsvHeader {
    <#
        Appended CSVs (overview, software) would silently lose new columns with Export-Csv -Append -Force.
        Lifts an existing file to the new column set once: old rows stay, new fields stay empty,
        extra columns written by the other tool are preserved. Port of Update-UebersichtKopf.
    #>
    param([string]$Path, [string[]]$Columns, [string]$Delimiter, [string]$Encoding, [string]$Label = 'overview')
    if (-not (Test-Path -LiteralPath $Path)) { return }
    $old = $null
    try { $old = @(Import-Csv -LiteralPath $Path -Delimiter $Delimiter -ErrorAction Stop) } catch {
        Write-Fail "$Label`: $Path is not readable - new columns cannot be added; the next row is appended without them."
        return
    }
    if ($old.Count -eq 0) {
        try {
            $head = Get-Content -LiteralPath $Path -TotalCount 1 -ErrorAction Stop
            $want = ($Columns | ForEach-Object { '"{0}"' -f $_ }) -join $Delimiter
            if ($head -and $head.Trim() -ne $want) { Remove-Item -LiteralPath $Path -Force -ErrorAction Stop; Write-Warn "$Label`: outdated header without rows removed, file is recreated." }
        } catch { $null = $_ }
        return
    }
    $have = @($old[0].PSObject.Properties.Name)
    if ($have -notcontains 'Hostname') {
        Write-Fail "$Label`: no 'Hostname' column in $Path - probably written with another delimiter than '$Delimiter'. File left untouched."
        return
    }
    $missing = @($Columns | Where-Object { $have -notcontains $_ })
    if ($missing.Count -eq 0) { return }
    $target = @($Columns) + @($have | Where-Object { $Columns -notcontains $_ })
    $backup = $Path -replace '\.csv$', ("_vor-Erweiterung_{0}.csv" -f (Get-Date -Format 'yyyyMMdd-HHmmss'))
    try { Copy-Item -LiteralPath $Path -Destination $backup -Force -ErrorAction Stop } catch { Write-Fail "$Label`: backup failed - file left untouched."; return }
    $new = foreach ($row in $old) {
        $o = [ordered]@{}
        foreach ($c in $target) { $o[$c] = if ($have -contains $c) { $row.$c } else { '' } }
        [pscustomobject]$o
    }
    try { $new | Export-Csv -Path $Path -Delimiter $Delimiter -NoTypeInformation -Encoding $Encoding -ErrorAction Stop }
    catch { Write-Fail "$Label`: could not be rewritten: $($_.Exception.Message) - original is in $backup"; return }
    Write-Warn ("{0}: extended with new columns: {1} (backup: {2})" -f $Label, ($missing -join ', '), $backup)
}

function Invoke-InventoryRun {
    <#
    .SYNOPSIS
        Collects the inventory and writes Inventar_<host>_<stamp>.csv (+ Inventar_Software.csv,
        Inventar_Uebersicht.csv). Returns @{ Detail; Software; Overview; Rows; WriteErrors }.
    #>
    param(
        [string]$OutputPath = (Get-InventoryOutputPath),
        [string]$Delimiter = $InventoryState.Delimiter,
        [string]$Comment = $InventoryState.Comment,
        [bool]$Summary = $InventoryState.Summary,
        [string]$Software = $InventoryState.Software,
        [bool]$Detail = $InventoryState.Detail
    )
    $ErrorActionPreference = 'SilentlyContinue'   # collection must never abort on a missing CIM class
    $Zeitstempel   = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
    $Aufnahmedatum = Get-Date -Format 'dd.MM.yyyy'
    $Dateistempel  = Get-Date -Format 'yyyyMMdd-HHmmss'
    $Rechnername   = $env:COMPUTERNAME
    if (-not $Rechnername) { $Rechnername = [Environment]::MachineName }
    $Zeilen  = New-Object System.Collections.Generic.List[object]
    $Kurz    = [ordered]@{}
    $SoftwareListe   = New-Object System.Collections.Generic.List[object]
    $SoftwareGesehen = New-Object 'System.Collections.Generic.HashSet[string]' -ArgumentList ([StringComparer]::OrdinalIgnoreCase)
    $IstAdmin = Test-IsAdmin

    function Add-Row {
        param([string]$Kategorie, [string]$Feld, $Wert)
        if ($null -eq $Wert) { return }
        $v = (($Wert | ForEach-Object { "$_" }) -join ', ').Trim()
        if ([string]::IsNullOrWhiteSpace($v)) { return }
        if ($v -match '^(To Be Filled By O\.E\.M\.|Default string|System manufacturer|Not Specified|None|Unknown)$') { return }
        $Zeilen.Add([pscustomobject]@{ Zeitstempel = $Zeitstempel; Hostname = $Rechnername; Kategorie = $Kategorie; Feld = $Feld; Wert = $v })
    }
    function Invoke-Section { param([string]$Name, [scriptblock]$Body) try { & $Body } catch { Add-Row 'Fehler' $Name $_.Exception.Message } }
    function ConvertFrom-WmiCharArray { param($Array) if (-not $Array) { return '' }; (($Array | Where-Object { $_ -ne 0 }) | ForEach-Object { [char]$_ }) -join '' }
    function Format-GB { param([double]$Bytes) if ($Bytes -le 0) { return '' }; '{0:N1}' -f ($Bytes / 1GB) }
    function Add-Software {
        param([string]$Typ, [string]$Name, [string]$Version, [string]$Hersteller, $Datum, [string]$Quelle)
        if ([string]::IsNullOrWhiteSpace($Name)) { return }
        $n = ($Name -replace '\s+', ' ').Trim(); $v = ("$Version" -replace '\s+', ' ').Trim(); $h = ("$Hersteller" -replace '\s+', ' ').Trim()
        if ($h -match 'CN=([^,]+)') { $h = $Matches[1].Trim() }
        if (-not $SoftwareGesehen.Add("$Typ|$n|$v")) { return }
        $d = ''
        if ($Datum) { try { $d = (Get-Date $Datum -Format 'yyyy-MM-dd') } catch { $d = '' } }
        $SoftwareListe.Add([pscustomobject]@{ Typ = $Typ; Name = $n; Version = $v; Hersteller = $h; Installiert = $d; Quelle = $Quelle })
    }
    function Get-InstallDatum {
        param($Eintrag)
        if ($Eintrag.InstallDate -match '^\d{8}$') { try { return [datetime]::ParseExact($Eintrag.InstallDate, 'yyyyMMdd', $null) } catch { $null = $_ } }
        if ($Eintrag.InstallLocation) {
            try {
                $ort = "$($Eintrag.InstallLocation)".Trim('"').TrimEnd('\')
                if ($ort -and (Test-Path -LiteralPath $ort)) { return (Get-Item -LiteralPath $ort -ErrorAction Stop).CreationTime }
            } catch { $null = $_ }
        }
        return $null
    }

    Write-Step 'Collecting inventory...'
    Add-Row 'Erfassung' 'Skriptversion'       "win-toolbox $ToolboxVersion"
    Add-Row 'Erfassung' 'Aufnahmedatum'       $Aufnahmedatum
    Add-Row 'Erfassung' 'Erfasst am'          $Zeitstempel
    Add-Row 'Erfassung' 'Erfasst von'         "$env:USERDOMAIN\$env:USERNAME"
    Add-Row 'Erfassung' 'Administratorrechte' $(if ($IstAdmin) { 'Ja' } else { 'Nein (einige Felder unvollstaendig)' })
    if ($Comment) { Add-Row 'Erfassung' 'Kommentar' $Comment }

    Invoke-Section 'System' {
        $cs = Get-CimInstance Win32_ComputerSystem; $bios = Get-CimInstance Win32_BIOS
        $prod = Get-CimInstance Win32_ComputerSystemProduct; $encl = Get-CimInstance Win32_SystemEnclosure
        $chassisMap = @{ 1='Other';2='Unbekannt';3='Desktop';4='Low Profile Desktop';5='Pizza Box';6='Mini Tower';7='Tower';8='Portable';9='Laptop';10='Notebook';11='Handheld';12='Docking Station';13='All in One';14='Sub Notebook';15='Space-Saving';16='Lunch Box';17='Main System Chassis';18='Expansion Chassis';21='Peripheral';23='Rack Mount';30='Tablet';31='Convertible';32='Detachable' }
        $formfaktor = ($encl.ChassisTypes | ForEach-Object { if ($chassisMap[[int]$_]) { $chassisMap[[int]$_] } else { "Typ $_" } }) -join ', '
        Add-Row 'System' 'Hostname' $Rechnername; Add-Row 'System' 'Hersteller' $cs.Manufacturer; Add-Row 'System' 'Modell' $cs.Model
        Add-Row 'System' 'Seriennummer' $bios.SerialNumber; Add-Row 'System' 'Asset-Tag' $encl.SMBIOSAssetTag; Add-Row 'System' 'UUID' $prod.UUID
        Add-Row 'System' 'Formfaktor' $formfaktor; Add-Row 'System' 'Domaene/Workgroup' $cs.Domain
        Add-Row 'System' 'Angemeldeter Benutzer' $cs.UserName; Add-Row 'System' 'Systemtyp' $cs.SystemType
        $Kurz['Hersteller'] = $cs.Manufacturer; $Kurz['Modell'] = $cs.Model; $Kurz['Seriennummer'] = $bios.SerialNumber
        $Kurz['AssetTag'] = $encl.SMBIOSAssetTag; $Kurz['Formfaktor'] = $formfaktor
    }
    Invoke-Section 'BIOS' {
        $bb = Get-CimInstance Win32_BaseBoard; $bios = Get-CimInstance Win32_BIOS
        Add-Row 'Mainboard' 'Hersteller' $bb.Manufacturer; Add-Row 'Mainboard' 'Modell' $bb.Product; Add-Row 'Mainboard' 'Seriennummer' $bb.SerialNumber
        Add-Row 'BIOS' 'Hersteller' $bios.Manufacturer
        Add-Row 'BIOS' 'Version' $(if ($bios.SMBIOSBIOSVersion) { $bios.SMBIOSBIOSVersion } else { $bios.Version })
        if ($bios.ReleaseDate) { Add-Row 'BIOS' 'Datum' (Get-Date $bios.ReleaseDate -Format 'yyyy-MM-dd') }
        $fw = if ((Get-CimInstance Win32_DiskPartition | Where-Object { $_.Type -like '*GPT*' })) { 'UEFI (vermutlich)' } else { '' }
        if ($env:firmware_type) { $fw = $env:firmware_type }
        Add-Row 'BIOS' 'Firmware-Modus' $fw
        $sb = try { Confirm-SecureBootUEFI } catch { $null }
        if ($null -ne $sb) { Add-Row 'BIOS' 'Secure Boot' $(if ($sb) { 'Aktiv' } else { 'Inaktiv' }) }
        $tpm = Get-CimInstance -Namespace 'root\cimv2\security\microsofttpm' -ClassName Win32_Tpm
        if ($tpm) { Add-Row 'BIOS' 'TPM vorhanden' 'Ja'; Add-Row 'BIOS' 'TPM Version' $tpm.SpecVersion; Add-Row 'BIOS' 'TPM aktiviert' $(if ($tpm.IsEnabled_InitialValue) { 'Ja' } else { 'Nein' }) }
        $Kurz['BIOS_Version'] = $bios.SMBIOSBIOSVersion
    }
    Invoke-Section 'Betriebssystem' {
        $os = Get-CimInstance Win32_OperatingSystem; $dv = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion'
        Add-Row 'Betriebssystem' 'Name' $os.Caption; Add-Row 'Betriebssystem' 'Edition/Release' $dv.DisplayVersion; Add-Row 'Betriebssystem' 'Version' $os.Version
        Add-Row 'Betriebssystem' 'Build' "$($dv.CurrentBuild).$($dv.UBR)"; Add-Row 'Betriebssystem' 'Architektur' $os.OSArchitecture; Add-Row 'Betriebssystem' 'Sprache' (Get-Culture).Name
        if ($os.InstallDate) { Add-Row 'Betriebssystem' 'Installiert am' (Get-Date $os.InstallDate -Format 'yyyy-MM-dd') }
        if ($os.LastBootUpTime) { Add-Row 'Betriebssystem' 'Letzter Start' (Get-Date $os.LastBootUpTime -Format 'yyyy-MM-dd HH:mm') }
        Add-Row 'Betriebssystem' 'PowerShell-Version' $PSVersionTable.PSVersion.ToString()
        $lic = Get-CimInstance SoftwareLicensingProduct -Filter "PartialProductKey IS NOT NULL AND ApplicationID='55c92734-d682-4d71-983e-d6ec3f16059f'" | Select-Object -First 1
        if ($lic) { Add-Row 'Betriebssystem' 'Lizenzstatus' $(if ($lic.LicenseStatus -eq 1) { 'Aktiviert' } else { "Status-Code $($lic.LicenseStatus)" }) }
        $Kurz['OS'] = $os.Caption; $Kurz['OSVersion'] = "$($dv.DisplayVersion) / $($dv.CurrentBuild).$($dv.UBR)"
    }
    Invoke-Section 'CPU' {
        $cpus = @(Get-CimInstance Win32_Processor); $i = 0
        foreach ($cpu in $cpus) {
            $i++; $p = if ($cpus.Count -gt 1) { "CPU $i " } else { '' }
            Add-Row 'CPU' "${p}Bezeichnung" $cpu.Name; Add-Row 'CPU' "${p}Hersteller" $cpu.Manufacturer; Add-Row 'CPU' "${p}Kerne" $cpu.NumberOfCores
            Add-Row 'CPU' "${p}Logische Kerne" $cpu.NumberOfLogicalProcessors; Add-Row 'CPU' "${p}Basistakt (MHz)" $cpu.MaxClockSpeed
            Add-Row 'CPU' "${p}Sockel" $cpu.SocketDesignation; Add-Row 'CPU' "${p}L3-Cache (KB)" $cpu.L3CacheSize
            Add-Row 'CPU' "${p}Virtualisierung" $(if ($cpu.VirtualizationFirmwareEnabled) { 'Aktiv' } else { 'Inaktiv/unbekannt' })
            if (-not $Kurz['CPU']) { $Kurz['CPU'] = ($cpu.Name -replace '\s+', ' ').Trim(); $Kurz['CPUKerne'] = "$($cpu.NumberOfCores)C/$($cpu.NumberOfLogicalProcessors)T" }
        }
    }
    Invoke-Section 'RAM' {
        $cs = Get-CimInstance Win32_ComputerSystem; $module = @(Get-CimInstance Win32_PhysicalMemory); $array = Get-CimInstance Win32_PhysicalMemoryArray | Select-Object -First 1
        $typMap = @{ 20='DDR'; 21='DDR2'; 24='DDR3'; 26='DDR4'; 34='DDR5'; 30='LPDDR4'; 35='LPDDR5' }
        Add-Row 'RAM' 'Gesamt (GB)' (Format-GB $cs.TotalPhysicalMemory); Add-Row 'RAM' 'Belegte Slots' $module.Count
        if ($array) { Add-Row 'RAM' 'Slots gesamt' $array.MemoryDevices }
        $n = 0
        foreach ($m in $module) {
            $n++
            $typ = if ($typMap[[int]$m.SMBIOSMemoryType]) { $typMap[[int]$m.SMBIOSMemoryType] } else { $m.MemoryType }
            $slot = if ($m.DeviceLocator) { $m.DeviceLocator } else { "Modul $n" }
            Add-Row 'RAM' "$slot - Groesse (GB)" (Format-GB $m.Capacity); Add-Row 'RAM' "$slot - Typ" $typ
            Add-Row 'RAM' "$slot - Takt (MHz)" $(if ($m.ConfiguredClockSpeed) { $m.ConfiguredClockSpeed } else { $m.Speed })
            Add-Row 'RAM' "$slot - Hersteller" $m.Manufacturer; Add-Row 'RAM' "$slot - Teilenummer" ($m.PartNumber -replace '\s+$', ''); Add-Row 'RAM' "$slot - Seriennummer" $m.SerialNumber
        }
        $Kurz['RAM_GB'] = Format-GB $cs.TotalPhysicalMemory; $Kurz['RAM_Module'] = ($module | ForEach-Object { "$(Format-GB $_.Capacity)GB" }) -join '+'
    }
    Invoke-Section 'Datentraeger' {
        $phys = @(Get-PhysicalDisk); $drives = @(Get-CimInstance Win32_DiskDrive | Sort-Object Index); $kurzDisks = @()
        foreach ($d in $drives) {
            $p = "Disk $($d.Index)"; $kurzDisks += ("{0}GB {1}" -f (Format-GB $d.Size), $d.Model).Trim()
            $pd = $phys | Where-Object { $_.DeviceId -eq "$($d.Index)" } | Select-Object -First 1
            Add-Row 'Datentraeger' "$p - Modell" $d.Model; Add-Row 'Datentraeger' "$p - Seriennummer" ($d.SerialNumber -replace '\s+', '')
            Add-Row 'Datentraeger' "$p - Groesse (GB)" (Format-GB $d.Size); Add-Row 'Datentraeger' "$p - Schnittstelle" $d.InterfaceType
            if ($pd) { Add-Row 'Datentraeger' "$p - Medientyp" $pd.MediaType; Add-Row 'Datentraeger' "$p - Bustyp" $pd.BusType; Add-Row 'Datentraeger' "$p - Zustand" $pd.HealthStatus }
            Add-Row 'Datentraeger' "$p - Partitionen" $d.Partitions
        }
        $Kurz['Disks'] = $kurzDisks -join ' | '
        foreach ($v in @(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3')) {
            Add-Row 'Volumes' "$($v.DeviceID) Label" $v.VolumeName; Add-Row 'Volumes' "$($v.DeviceID) Dateisystem" $v.FileSystem
            Add-Row 'Volumes' "$($v.DeviceID) Groesse (GB)" (Format-GB $v.Size); Add-Row 'Volumes' "$($v.DeviceID) Frei (GB)" (Format-GB $v.FreeSpace)
        }
        $bl = Get-CimInstance -Namespace 'root\cimv2\security\microsoftvolumeencryption' -ClassName Win32_EncryptableVolume
        foreach ($b in @($bl)) { $st = switch ($b.ProtectionStatus) { 0 { 'Aus' } 1 { 'Aktiv' } 2 { 'Unbekannt' } }; Add-Row 'Volumes' "$($b.DriveLetter) BitLocker" $st }
    }
    Invoke-Section 'GPU' {
        $n = 0
        foreach ($g in @(Get-CimInstance Win32_VideoController)) {
            $n++; $p = "GPU $n"
            Add-Row 'GPU' "$p - Bezeichnung" $g.Name; Add-Row 'GPU' "$p - VRAM (GB)" (Format-GB $g.AdapterRAM); Add-Row 'GPU' "$p - Treiberversion" $g.DriverVersion
            Add-Row 'GPU' "$p - Aufloesung" $(if ($g.CurrentHorizontalResolution) { "$($g.CurrentHorizontalResolution)x$($g.CurrentVerticalResolution)" })
            if (-not $Kurz['GPU']) { $Kurz['GPU'] = $g.Name }
        }
    }
    Invoke-Section 'Monitore' {
        $ids = @(Get-CimInstance -Namespace 'root\wmi' -ClassName WmiMonitorID); $n = 0
        foreach ($m in $ids) {
            $n++; $p = "Monitor $n"
            Add-Row 'Monitore' "$p - Hersteller" (ConvertFrom-WmiCharArray $m.ManufacturerName); Add-Row 'Monitore' "$p - Modell" (ConvertFrom-WmiCharArray $m.UserFriendlyName)
            Add-Row 'Monitore' "$p - Seriennummer" (ConvertFrom-WmiCharArray $m.SerialNumberID); Add-Row 'Monitore' "$p - Baujahr" $m.YearOfManufacture
        }
        Add-Row 'Monitore' 'Anzahl' $ids.Count; $Kurz['Monitore'] = $ids.Count
    }
    Invoke-Section 'Netzwerk' {
        $adapter = @(Get-CimInstance Win32_NetworkAdapter -Filter 'PhysicalAdapter=TRUE AND MACAddress IS NOT NULL')
        foreach ($a in $adapter) {
            $p = $a.NetConnectionID; if (-not $p) { $p = $a.Name }
            $cfg = Get-CimInstance Win32_NetworkAdapterConfiguration -Filter "Index=$($a.Index)"
            Add-Row 'Netzwerk' "$p - Bezeichnung" $a.Name; Add-Row 'Netzwerk' "$p - MAC" $a.MACAddress
            Add-Row 'Netzwerk' "$p - Status" $(if ($a.NetEnabled) { 'Verbunden/aktiv' } else { 'Inaktiv' })
            if ($a.Speed -and $a.Speed -lt 1e15) { Add-Row 'Netzwerk' "$p - Geschwindigkeit (Mbit/s)" ([math]::Round($a.Speed / 1MB)) }
            if ($cfg.IPAddress) { Add-Row 'Netzwerk' "$p - IP" ($cfg.IPAddress -join ', ') }
            if ($cfg.DefaultIPGateway) { Add-Row 'Netzwerk' "$p - Gateway" ($cfg.DefaultIPGateway -join ', ') }
        }
        $primaer = $adapter | Where-Object { $_.NetEnabled } | Select-Object -First 1
        if ($primaer) {
            $Kurz['MAC_Primaer'] = $primaer.MACAddress
            $cfg = Get-CimInstance Win32_NetworkAdapterConfiguration -Filter "Index=$($primaer.Index)"
            $Kurz['IP_Primaer'] = ($cfg.IPAddress | Where-Object { $_ -notmatch ':' }) -join ', '
        }
    }
    Invoke-Section 'Akku' {
        $bat = Get-CimInstance Win32_Battery | Select-Object -First 1
        if (-not $bat) { return }
        Add-Row 'Akku' 'Bezeichnung' $bat.Name; Add-Row 'Akku' 'Ladestand (%)' $bat.EstimatedChargeRemaining
        $design = (Get-CimInstance -Namespace 'root\wmi' -ClassName BatteryStaticData | Select-Object -First 1).DesignedCapacity
        $full = (Get-CimInstance -Namespace 'root\wmi' -ClassName BatteryFullChargedCapacity | Select-Object -First 1).FullChargedCapacity
        if ($design -and $full) {
            $health = [math]::Round(($full / $design) * 100, 1)
            Add-Row 'Akku' 'Design-Kapazitaet (mWh)' $design; Add-Row 'Akku' 'Aktuelle Kapazitaet (mWh)' $full; Add-Row 'Akku' 'Gesundheit (%)' $health
            $Kurz['Akku_Gesundheit_Prozent'] = $health
        }
    }
    Invoke-Section 'Software' {
        if ($Software -eq 'none') { return }
        Write-Step 'Collecting installed software...'
        $regPfade = @(
            @{ P = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall';             Q = 'Registry HKLM' }
            @{ P = 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'; Q = 'Registry HKLM 32-Bit' }
            @{ P = 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall';             Q = 'Registry HKCU' }
        )
        foreach ($hive in (Get-ChildItem 'Registry::HKEY_USERS' -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^S-1-5-21-[\d-]+$' })) {
            $regPfade += @{ P = "Registry::$($hive.Name)\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"; Q = 'Registry Benutzerprofil' }
            $regPfade += @{ P = "Registry::$($hive.Name)\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall"; Q = 'Registry Benutzerprofil 32-Bit' }
        }
        foreach ($rp in $regPfade) {
            if (-not (Test-Path -LiteralPath $rp.P)) { continue }
            foreach ($k in (Get-ChildItem -LiteralPath $rp.P -ErrorAction SilentlyContinue)) {
                $e = Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue
                if (-not $e -or -not $e.DisplayName) { continue }
                if ($e.SystemComponent -eq 1) { continue }
                if ($e.ParentKeyName) { continue }
                if ($e.ReleaseType -match 'Update|Hotfix|Security') { continue }
                Add-Software 'Programm' $e.DisplayName $e.DisplayVersion $e.Publisher (Get-InstallDatum $e) $rp.Q
            }
        }
        $appx = @()
        try { $appx = @(Get-AppxPackage -AllUsers -ErrorAction SilentlyContinue) } catch { $null = $_ }
        if ($appx.Count -eq 0) { try { $appx = @(Get-AppxPackage -ErrorAction SilentlyContinue) } catch { $null = $_ } }
        foreach ($a in $appx) {
            if ($a.IsFramework -or $a.IsResourcePackage) { continue }
            $d = $null
            if ($a.InstallLocation) { try { $d = (Get-Item -LiteralPath $a.InstallLocation -ErrorAction Stop).CreationTime } catch { $null = $_ } }
            Add-Software 'Store-App' $a.Name $a.Version $a.Publisher $d 'Appx'
        }
        if ($Software -ne 'noupdates') {
            foreach ($h in (Get-HotFix -ErrorAction SilentlyContinue)) {
                $q = if ($h.Description) { "Windows Update ($($h.Description))" } else { 'Windows Update' }
                Add-Software 'Windows-Update' $h.HotFixID '' 'Microsoft' $h.InstalledOn $q
            }
        }
        $programme = @($SoftwareListe | Where-Object { $_.Typ -eq 'Programm' }); $storeApps = @($SoftwareListe | Where-Object { $_.Typ -eq 'Store-App' })
        $updates = @($SoftwareListe | Where-Object { $_.Typ -eq 'Windows-Update' }); $anzahl = $programme.Count + $storeApps.Count
        Add-Row 'Software' 'Anzahl gesamt' $anzahl; Add-Row 'Software' 'Davon Programme' $programme.Count; Add-Row 'Software' 'Davon Store-Apps' $storeApps.Count
        if ($Software -ne 'noupdates') { Add-Row 'Software' 'Windows-Updates' $updates.Count }
        $mitDatum = @($programme + $storeApps | Where-Object { $_.Installiert })
        $neueste = $mitDatum | Sort-Object Installiert -Descending | Select-Object -First 1
        if ($neueste) { Add-Row 'Software' 'Zuletzt installiert' ("{0} - {1}" -f $neueste.Installiert, $neueste.Name) }
        Add-Row 'Software' 'Ohne Installationsdatum' ($anzahl - $mitDatum.Count)
        $Kurz['Software_Anzahl'] = $anzahl; $Kurz['Software_Neueste_Installation'] = ''
        if ($neueste) { $Kurz['Software_Neueste_Installation'] = $neueste.Installiert }
        if ($Detail) {
            foreach ($s in ($programme + $storeApps | Sort-Object Name)) {
                $wert = @(@($s.Version, $s.Hersteller) | Where-Object { $_ })
                if ($s.Installiert) { $wert += "installiert am $($s.Installiert)" }
                $text = $wert -join ' | '
                if (-not $text) { $text = '(keine weiteren Angaben)' }
                Add-Row 'Software' $s.Name $text
            }
        }
    }

    # ---- write ---------------------------------------------------------------
    $ErrorActionPreference = 'Stop'
    $writeErrors = 0
    function Write-InventoryCsv {
        param([Parameter(Mandatory)]$Data, [Parameter(Mandatory)][string]$Path, [switch]$Append, [string]$Label)
        try {
            if ($Append) { $Data | Export-Csv -Path $Path -Delimiter $Delimiter -NoTypeInformation -Encoding $enc -Append -Force -ErrorAction Stop }
            else { $Data | Export-Csv -Path $Path -Delimiter $Delimiter -NoTypeInformation -Encoding $enc -ErrorAction Stop }
            if (-not (Test-Path -LiteralPath $Path)) { throw 'file does not exist after writing' }
            return $true
        } catch {
            Write-Fail ("{0} could not be written: {1} ({2})" -f $Label, $_.Exception.Message, $Path)
            return $false
        }
    }
    if ($Delimiter.Length -ne 1) { throw "'$Delimiter' is not a valid delimiter - it must be exactly one character." }
    if (-not (Test-Path -LiteralPath $OutputPath)) { New-Item -ItemType Directory -Path $OutputPath -Force | Out-Null }
    $enc = if ($PSVersionTable.PSVersion.Major -ge 6) { 'utf8BOM' } else { 'UTF8' }
    $result = @{ Detail = $null; Software = $null; Overview = $null; Rows = $Zeilen.Count; WriteErrors = 0 }

    $detailDatei = Join-Path $OutputPath ("Inventar_{0}_{1}.csv" -f $Rechnername, $Dateistempel)
    if (Write-InventoryCsv -Data $Zeilen -Path $detailDatei -Label 'Detail CSV') { $result.Detail = $detailDatei; Write-Ok "Detail CSV : $detailDatei ($($Zeilen.Count) rows)" } else { $writeErrors++ }

    if ($Software -ne 'none' -and $SoftwareListe.Count -gt 0) {
        $softwareDatei = Join-Path $OutputPath 'Inventar_Software.csv'
        $swSpalten = @('Zeitstempel','Aufnahmedatum','Hostname','Typ','Name','Version','Hersteller','Installiert_am','Quelle')
        Update-CsvHeader -Path $softwareDatei -Columns $swSpalten -Delimiter $Delimiter -Encoding $enc -Label 'Software CSV'
        $swZeilen = $SoftwareListe | Sort-Object Typ, Name |
            Select-Object @{L='Zeitstempel';E={$Zeitstempel}}, @{L='Aufnahmedatum';E={$Aufnahmedatum}}, @{L='Hostname';E={$Rechnername}},
                          Typ, Name, Version, Hersteller, @{L='Installiert_am';E={$_.Installiert}}, Quelle
        if (Write-InventoryCsv -Data $swZeilen -Path $softwareDatei -Append -Label 'Software CSV') { $result.Software = $softwareDatei; Write-Ok "Software CSV: $softwareDatei (+$($SoftwareListe.Count) rows)" } else { $writeErrors++ }
    }
    if ($Summary) {
        $uebersicht = Join-Path $OutputPath 'Inventar_Uebersicht.csv'
        $spalten = @('Zeitstempel','Aufnahmedatum','Hostname','Kommentar','Hersteller','Modell','Seriennummer','AssetTag','Formfaktor','OS','OSVersion','CPU','CPUKerne',
                     'RAM_GB','RAM_Module','Disks','GPU','MAC_Primaer','IP_Primaer','BIOS_Version','Akku_Gesundheit_Prozent','Monitore','Software_Anzahl','Software_Neueste_Installation')
        Update-CsvHeader -Path $uebersicht -Columns $spalten -Delimiter $Delimiter -Encoding $enc -Label 'Overview CSV'
        $zeile = [ordered]@{ Zeitstempel = $Zeitstempel; Aufnahmedatum = $Aufnahmedatum; Hostname = $Rechnername; Kommentar = $Comment }
        foreach ($k in $spalten) { if (-not $zeile.Contains($k)) { $zeile[$k] = $Kurz[$k] } }
        if (Write-InventoryCsv -Data ([pscustomobject]$zeile) -Path $uebersicht -Append -Label 'Overview CSV') { $result.Overview = $uebersicht; Write-Ok "Overview CSV: $uebersicht (appended)" } else { $writeErrors++ }
    }
    $result.WriteErrors = $writeErrors
    if ($writeErrors -gt 0) { Write-Fail "$writeErrors file(s) could not be written - the inventory is incomplete." }
    if (-not $IstAdmin) { Write-Warn 'Ran without administrator rights - TPM, battery and some disk/RAM details may be missing.' }
    return $result
}

function Invoke-Inventory {
    <# Menu entry: options menu, then the run. #>
    Write-Title 'Inventory'
    while (Show-InventoryMenu) {
        Clear-Host
        Write-Title 'Inventory'
        $null = Invoke-InventoryRun
        Wait-AnyKey 'Press any key to return to the Inventory menu...'
    }
}

# ---------------------------------------------------------------------------
# tools/traces.ps1 - remove the technician's working traces in the current user's account.
# English port of Spuren-Entfernen.ps1. Runs in the CONTEXT OF THE LOGGED-IN USER (HKCU +
# profile), not as admin - otherwise it would clean the admin profile. Dry run is the default;
# only "Execute" actually deletes. Deliberately does NOT touch Windows event logs (they belong
# to the device owner) or the USB device history.
# ---------------------------------------------------------------------------

$TraceState = @{
    Execute    = $false
    History    = $true
    Dialogs    = $true
    Recent     = $true
    Temp       = $true
    RecycleBin = $false
}
$TraceCounters = @{ Removed = 0; Skipped = 0; Errors = 0 }

function Remove-Trace {
    <# Removes one target if present, honouring dry-run and counting. #>
    param([Parameter(Mandatory)][string]$What, [scriptblock]$Action, [scriptblock]$Present = { $true })
    $there = $false
    try { $there = [bool](& $Present) } catch { $there = $false }
    if (-not $there) { return }
    if (-not $TraceState.Execute) {
        Write-Host ("   [would] {0}" -f $What) -ForegroundColor Yellow
        $TraceCounters.Skipped++
        return
    }
    try { & $Action; Write-Host ("   [gone] {0}" -f $What) -ForegroundColor Green; $TraceCounters.Removed++ }
    catch { Write-Host ("   [X]    {0} - {1}" -f $What, $_.Exception.Message) -ForegroundColor Red; $TraceCounters.Errors++ }
}

function Remove-RegValue {
    param([string]$Path, [string]$Name, [string]$What)
    Remove-Trace -What $What `
        -Present { (Test-Path -LiteralPath $Path) -and ($null -ne (Get-ItemProperty -LiteralPath $Path -Name $Name -ErrorAction SilentlyContinue)) } `
        -Action  { Remove-ItemProperty -LiteralPath $Path -Name $Name -Force -ErrorAction Stop }
}

function Clear-RegKey {
    param([string]$Path, [string]$What)
    Remove-Trace -What $What `
        -Present { (Test-Path -LiteralPath $Path) -and ((@(Get-ChildItem -LiteralPath $Path -ErrorAction SilentlyContinue).Count -gt 0) -or (@((Get-Item -LiteralPath $Path -ErrorAction SilentlyContinue).Property).Count -gt 0)) } `
        -Action  {
            Get-ChildItem -LiteralPath $Path -ErrorAction SilentlyContinue | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
            foreach ($n in (Get-Item -LiteralPath $Path).Property) { if ($n -ne '(Default)') { Remove-ItemProperty -LiteralPath $Path -Name $n -Force -ErrorAction SilentlyContinue } }
        }
}

function Clear-ShellHistory {
    Write-Host ''; Write-Host '== Shell history' -ForegroundColor Cyan
    $psr = $null
    try { $psr = (Get-PSReadLineOption -ErrorAction SilentlyContinue).HistorySavePath } catch { $null = $_ }
    if (-not $psr) { $psr = Join-Path $env:APPDATA 'Microsoft\Windows\PowerShell\PSReadLine\ConsoleHost_history.txt' }
    Remove-Trace -What ("PowerShell history file: {0}" -f $psr) -Present { Test-Path -LiteralPath $psr } -Action { Remove-Item -LiteralPath $psr -Force -ErrorAction Stop }
    if ($TraceState.Execute) {
        try { Clear-History -ErrorAction SilentlyContinue } catch { $null = $_ }
        try { [Microsoft.PowerShell.PSConsoleReadLine]::ClearHistory() } catch { $null = $_ }
    }
    Write-Host '   CMD keeps no on-disk history - nothing to remove.' -ForegroundColor DarkGray
}

function Clear-Dialogs {
    Write-Host ''; Write-Host '== Run dialog and address bars' -ForegroundColor Cyan
    $hk = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer'
    Clear-RegKey "$hk\RunMRU"                      'Run dialog (Win+R)'
    Clear-RegKey "$hk\TypedPaths"                  'Explorer address bar (typed paths)'
    Clear-RegKey "$hk\RecentDocs"                  'Recently opened documents (RecentDocs)'
    Clear-RegKey "$hk\ComDlg32\LastVisitedPidlMRU" 'Open/Save - last visited folders'
    Clear-RegKey "$hk\ComDlg32\OpenSavePidlMRU"    'Open/Save - last used files'
    Clear-RegKey "$hk\WordWheelQuery"              'Explorer search box history'
}

function Clear-RecentItems {
    Write-Host ''; Write-Host '== Recent items and jump lists' -ForegroundColor Cyan
    $recent = Join-Path $env:APPDATA 'Microsoft\Windows\Recent'
    foreach ($u in @($recent, (Join-Path $recent 'AutomaticDestinations'), (Join-Path $recent 'CustomDestinations'))) {
        Remove-Trace -What ("Contents of {0}" -f $u) `
            -Present { (Test-Path -LiteralPath $u) -and (@(Get-ChildItem -LiteralPath $u -Force -ErrorAction SilentlyContinue).Count -gt 0) } `
            -Action  { Get-ChildItem -LiteralPath $u -Force -ErrorAction SilentlyContinue | Remove-Item -Force -Recurse -ErrorAction SilentlyContinue }
    }
}

function Clear-TempFiles {
    Write-Host ''; Write-Host '== Temporary files' -ForegroundColor Cyan
    $targets = @($env:TEMP)
    if (Test-IsAdmin) { $targets += (Join-Path $env:SystemRoot 'Temp') }
    foreach ($t in ($targets | Select-Object -Unique)) {
        if (-not (Test-Path -LiteralPath $t)) { continue }
        $count = 0
        try { $count = @(Get-ChildItem -LiteralPath $t -Force -ErrorAction SilentlyContinue).Count } catch { $null = $_ }
        if ($count -eq 0) { continue }
        Remove-Trace -What ("{0} entries in {1}" -f $count, $t) -Present { $true } `
            -Action { Get-ChildItem -LiteralPath $t -Force -ErrorAction SilentlyContinue | ForEach-Object { try { Remove-Item -LiteralPath $_.FullName -Force -Recurse -ErrorAction Stop } catch { $null = $_ } } }
    }
}

function Clear-RecycleBinTrace {
    Write-Host ''; Write-Host '== Recycle bin' -ForegroundColor Cyan
    if (-not $TraceState.Execute) { Write-Host '   [would] empty the recycle bin' -ForegroundColor Yellow; $TraceCounters.Skipped++; return }
    try { Clear-RecycleBin -Force -ErrorAction Stop; Write-Host '   [gone] recycle bin emptied' -ForegroundColor Green; $TraceCounters.Removed++ }
    catch {
        $hr = 0; try { $hr = $_.Exception.HResult } catch { $null = $_ }
        if ($hr -eq -2147418113 -or $hr -eq -2147024751 -or "$($_.Exception.Message)" -match 'empty') { Write-Host '   recycle bin was already empty.' -ForegroundColor DarkGray }
        else { Write-Host ("   [X]    recycle bin: {0}" -f $_.Exception.Message) -ForegroundColor Red; $TraceCounters.Errors++ }
    }
}

function Show-TracesMenu {
    <# Returns $true to run, $false to go back. #>
    while ($true) {
        Clear-Host
        Write-Title 'Clean Traces'
        Write-Host '   Removes the technician''s working traces in the CURRENT user account (HKCU + profile).' -ForegroundColor DarkGray
        Write-Host '   Event logs and USB device history are deliberately left alone.' -ForegroundColor DarkGray
        Write-Host ''
        $on = { param($b) if ($b) { 'on ' } else { 'off' } }
        Write-Host ("   [1] Shell history   : {0}  PSReadLine file + current session" -f (& $on $TraceState.History))
        Write-Host ("   [2] Dialogs         : {0}  Run (Win+R), address bar, open/save, RecentDocs" -f (& $on $TraceState.Dialogs))
        Write-Host ("   [3] Recent items    : {0}  Recent folder and jump lists" -f (& $on $TraceState.Recent))
        Write-Host ("   [4] Temp files      : {0}  %TEMP% (+ C:\Windows\Temp when admin)" -f (& $on $TraceState.Temp))
        Write-Host ("   [5] Recycle bin     : {0}  empty the recycle bin (off by default)" -f (& $on $TraceState.RecycleBin))
        Write-Host ''
        $modeText = if ($TraceState.Execute) { 'EXECUTE - will delete' } else { 'dry run - shows only what would be removed' }
        $modeColor = if ($TraceState.Execute) { 'Red' } else { 'Yellow' }
        Write-Host ("   [m] Mode            : {0}" -f $modeText) -ForegroundColor $modeColor
        Write-Host ''
        Write-Host '   [Enter] run          [q] back' -ForegroundColor Green
        Write-Host ''
        $e = (Read-MenuLine '  Choice').ToLower()
        switch ($e) {
            ''  { return $true }
            'q' { return $false }
            '1' { $TraceState.History = -not $TraceState.History }
            '2' { $TraceState.Dialogs = -not $TraceState.Dialogs }
            '3' { $TraceState.Recent = -not $TraceState.Recent }
            '4' { $TraceState.Temp = -not $TraceState.Temp }
            '5' { $TraceState.RecycleBin = -not $TraceState.RecycleBin }
            'm' {
                if (-not $TraceState.Execute) {
                    if (Confirm-Action '  Switch to EXECUTE (this will delete)?') { $TraceState.Execute = $true }
                } else { $TraceState.Execute = $false }
            }
        }
    }
}

function Invoke-TracesRun {
    <# Runs the selected categories. Returns the counters hashtable. #>
    $TraceCounters.Removed = 0; $TraceCounters.Skipped = 0; $TraceCounters.Errors = 0
    $log = Start-Log -Name 'clean-traces'
    Write-Title 'Clean Traces'
    Write-Host ("   Host: {0}   User: {1}" -f $env:COMPUTERNAME, $env:USERNAME) -ForegroundColor DarkGray
    if ($TraceState.Execute) { Write-Host '   Mode: DELETING' -ForegroundColor Red } else { Write-Host '   Mode: dry run - nothing is deleted' -ForegroundColor Yellow }
    Write-LogLine ("mode: {0}" -f $(if ($TraceState.Execute) { 'execute' } else { 'dry run' }))

    if ($TraceState.History) { Clear-ShellHistory }
    if ($TraceState.Dialogs) { Clear-Dialogs }
    if ($TraceState.Recent) { Clear-RecentItems }
    if ($TraceState.Temp) { Clear-TempFiles }
    if ($TraceState.RecycleBin) { Clear-RecycleBinTrace }

    Write-Host ''
    if ($TraceState.Execute) {
        Write-Host ("   Removed: {0}   Errors: {1}" -f $TraceCounters.Removed, $TraceCounters.Errors) -ForegroundColor $(if ($TraceCounters.Errors) { 'Yellow' } else { 'Green' })
    } else {
        Write-Host ("   Dry run: {0} items would be removed. Switch mode to [m] EXECUTE to delete." -f $TraceCounters.Skipped) -ForegroundColor Yellow
    }
    if ($TraceState.Execute -and ($TraceState.Dialogs -or $TraceState.Recent)) {
        Write-Host '   Note: jump lists and history disappear from the UI only after restarting Explorer or signing in again.' -ForegroundColor DarkGray
    }
    if ($log) { Write-Host ("   Log: {0}" -f $log) -ForegroundColor DarkGray }
    return $TraceCounters
}

function Invoke-CleanTraces {
    <# Menu entry: options menu (dry-run default), then the run. #>
    while (Show-TracesMenu) {
        $null = Invoke-TracesRun
        Wait-AnyKey 'Press any key to return to the Clean Traces menu...'
    }
}

